private List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || start >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("start must be between 0 and " + FETCH_DATA_DURATION);
    }
    if (end < start || end >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("end must be between start and " + FETCH_DATA_DURATION);
    }
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    long currentEnd = Math.min(end, FETCH_DATA_DURATION);
    while (currentStart < currentEnd) {
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

