    String parentPath = path.substring(0,lastSeparatorIdx);
    String currentFile = path.substring(lastSeparatorIdx + 1);
    if(relativePath.startsWith("/")){
        return path.substring(0,path.length() - currentFile.length()) + relativePath.substring(1);
    }else{
        return parentPath + "/" + relativePath;
    }
}

